// lib/hotel-details.ts
import type { SearchParams } from "@/lib/hotels";

/* ------------------------------------------------------------------ */
/* Raw Hotelbeds Content API shapes (only the fields we use)           */
/* ------------------------------------------------------------------ */

type Localized = { languageCode?: string; content?: string };

type RawFacility = {
  facilityCode: number;
  facilityGroupCode: number;
  description?: Localized;
  indLogic?: boolean;
  indYesOrNo?: boolean;
  indFee?: boolean;
  number?: number;
  distance?: number; // metres
  timeFrom?: string;
  timeTo?: string;
};

type RawRoom = {
  roomCode: string;
  isParentRoom?: boolean;
  minPax?: number;
  maxPax?: number;
  maxAdults?: number;
  maxChildren?: number;
  description?: string;
  type?: { description?: Localized };
  characteristic?: { description?: Localized };
  roomFacilities?: RawFacility[];
  roomStays?: {
    roomStayFacilities?: { description?: Localized; number?: number }[];
  }[];
};

type RawImage = {
  type?: { code: string; description?: Localized };
  path: string;
  roomCode?: string;
  visualOrder: number;
};

export type RawHotel = {
  code: number;
  name?: Localized;
  description?: Localized;
  country?: { description?: Localized };
  destination?: { name?: Localized };
  coordinates?: { latitude: number; longitude: number };
  category?: { code?: string; description?: Localized };
  address?: { content?: string; street?: string; number?: string };
  postalCode?: string;
  city?: Localized;
  rooms?: RawRoom[];
  facilities?: RawFacility[];
  terminals?: { distance: number; name?: Localized; description?: Localized }[];
  images?: RawImage[];
  wildcards?: { roomType: string; hotelRoomDescription?: Localized }[];
  web?: string;
};

type HotelDetailsResponse = {
  success: boolean;
  message?: string;
  data?: { hotel?: RawHotel };
};

/* ------------------------------------------------------------------ */
/* Raw Hotelbeds availability shapes (standard Booking API format)     */
/* ------------------------------------------------------------------ */

type RawTax = {
  included?: boolean;
  amount?: string;
  currency?: string;
  clientAmount?: string;
  clientCurrency?: string;
};

type RawRate = {
  rateKey: string;
  rateType?: string; // BOOKABLE | RECHECK
  net?: string;
  sellingRate?: string;
  allotment?: number;
  paymentType?: string; // AT_WEB | AT_HOTEL
  boardCode?: string;
  boardName?: string;
  cancellationPolicies?: { amount?: string; from: string }[];
  taxes?: { allIncluded?: boolean; taxes?: RawTax[] };
};

type RawAvailRoom = { code: string; name?: string; rates?: RawRate[] };

export type RawAvailHotel = {
  code: number;
  currency?: string;
  rooms?: RawAvailRoom[];
};

/* ------------------------------------------------------------------ */
/* View model used by the UI                                           */
/* ------------------------------------------------------------------ */

export type IconKey =
  | "beach" | "wifi" | "pool" | "plane" | "spa"
  | "food" | "bar" | "gym" | "car" | "clock";

export type IconLabel = { label: string; icon: string };

export type RateView = {
  key: string;
  board: string;
  cancel: string;
  payment?: string;
  taxNote?: string;
  allotment: number;
  total: string;
  sub?: string;
  amount: number;
  href: string;
};

export type RoomView = {
  code: string;
  title: string;
  type: string;
  characteristic: string;
  minPax?: number;
  maxPax?: number;
  maxAdults?: number;
  maxChildren?: number;
  beds: string[];
  facilities: IconLabel[];
  images: { full: string; thumb: string }[];
  rates: RateView[];
};

export type HotelView = {
  id: number;
  name: string;
  stars: number; // 0 when unknown
  location: string;
  heading: string;
  description: string;
  features: { label: string; icon: IconKey }[];
  photos: { src: string; alt: string }[]; // first 5 only
  photoCount: number;
  rooms: RoomView[];
  facilities: IconLabel[];
  distances: { label: string; value: string }[];
  address: string;
  checkIn?: string;
  checkOut?: string;
  mapUrl?: string;
  /** true once an availability search for the chosen dates returned */
  priced: boolean;
  /** e.g. "Fri, Nov 6 – Mon, Nov 9 · 3 nights" (only when dates were chosen) */
  stayLabel?: string;
  fromPrice?: string; // "€120" per night, cheapest rate
  // The Hotelbeds Content API has NO guest reviews. Fill this from your own
  // review source later; while it is null the score box is hidden.
  review: { score: number; label: string; count: number } | null;
};

/* ------------------------------------------------------------------ */
/* Fetching                                                            */
/* ------------------------------------------------------------------ */

const API_BASE = () => process.env.API_BASE_URL ?? "http://localhost:3000";

export async function fetchHotelDetails(id: string): Promise<RawHotel | null> {
  if (!/^\d+$/.test(id)) return null;

  const url = `${API_BASE()}/api/v1/hotels/${id}/details?language=ENG&useSecondaryLanguage=true`;
  const res = await fetch(url, { next: { revalidate: 3600 } });
  if (res.status === 404) return null;
  if (!res.ok) throw new Error(`Hotel details request failed (${res.status})`);

  const json = (await res.json()) as HotelDetailsResponse;
  return json.success && json.data?.hotel ? json.data.hotel : null;
}

/**
 * ⚠️ ASSUMPTION – adjust the URL / body to your backend.
 * Sends a standard Hotelbeds availability request for ONE hotel and returns
 * that hotel's block (hotel.rooms[].rates[]). Never throws: returns null on any failure.
 */
export async function fetchHotelAvailability(
  id: string,
  s: SearchParams
): Promise<RawAvailHotel | null> {
  if (!s.checkIn || !s.checkOut) return null;

  const occupancy = {
    rooms: Math.max(1, s.rooms),
    adults: Math.max(1, s.adults),
    children: s.children,
    // Hotelbeds needs an age for each child; replace 8 with real ages when you collect them
    ...(s.children > 0
      ? { paxes: Array.from({ length: s.children }, () => ({ type: "CH", age: 8 })) }
      : {}),
  };

  try {
    const res = await fetch(`${API_BASE()}/api/v1/hotels/availability`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      cache: "no-store",
      body: JSON.stringify({
        stay: { checkIn: s.checkIn, checkOut: s.checkOut },
        occupancies: [occupancy],
        hotels: { hotel: [Number(id)] },
      }),
    });
    if (!res.ok) return null;
    return extractAvailHotel(await res.json(), Number(id));
  } catch {
    return null;
  }
}

// Accepts { data: { hotels: { hotels: [...] } } }, { data: { hotels: [...] } } or { hotels: { hotels: [...] } }
function extractAvailHotel(json: any, code: number): RawAvailHotel | null {
  const root = json?.data ?? json;
  const list: RawAvailHotel[] =
    root?.hotels?.hotels ?? (Array.isArray(root?.hotels) ? root.hotels : []);
  return list.find((h) => Number(h.code) === code) ?? null;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

const IMAGE_BASE = "https://photos.hotelbeds.com/giata";
const SMALL_WORDS = new Set(["de", "del", "la", "las", "los", "el", "y", "of", "and", "da", "do"]);
const MAX_IMAGES_PER_ROOM = 12;

function titleCase(s = ""): string {
  return s
    .trim()
    .toLowerCase()
    .split(/\s+/)
    .filter(Boolean)
    .map((w, i) => (i > 0 && SMALL_WORDS.has(w) ? w : w.charAt(0).toUpperCase() + w.slice(1)))
    .join(" ");
}

function formatDistance(metres: number): string {
  return metres < 1000 ? `${metres} m` : `${+(metres / 1000).toFixed(1)} km`;
}

function money(amount: number, currency = "EUR"): string {
  try {
    return new Intl.NumberFormat("en-US", { style: "currency", currency }).format(amount);
  } catch {
    return `${currency} ${amount.toFixed(2)}`;
  }
}

function shortDate(iso: string): string {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return "";
  return d.toLocaleDateString("en-GB", { day: "numeric", month: "short", year: "numeric", timeZone: "UTC" });
}

const fkey = (f: RawFacility) => `${f.facilityGroupCode}-${f.facilityCode}`;

// indLogic / indYesOrNo === false means "not available"
const isPresent = (f?: RawFacility): f is RawFacility =>
  !!f && f.indLogic !== false && f.indYesOrNo !== false;

function imageUrl(path: string, size: "bigger" | "medium"): string {
  return `${IMAGE_BASE}/${size}/${path.split("?")[0]}`;
}

function parseStars(h: RawHotel): number {
  const fromCode = /^(\d)/.exec(h.category?.code ?? "");
  if (fromCode) return Number(fromCode[1]);
  const fromText = /(\d)/.exec(h.category?.description?.content ?? "");
  return fromText ? Number(fromText[1]) : 0;
}

/* ------------------------------ icons ------------------------------ */

// Room facilities (facilityGroupCode 60) by facilityCode
const ROOM_ICONS: Record<number, string> = {
  10: "🚿", 20: "🚿", 30: "🛁", 40: "💨", 50: "☎️", 55: "📺", 80: "📻", 90: "🔊",
  100: "🌐", 120: "🍷", 143: "☕", 160: "🧶", 170: "❄️", 180: "❄️", 190: "🔥", 195: "🔥",
  200: "🔒", 220: "🛋", 230: "🌅", 240: "🌿", 250: "♿", 260: "♿", 261: "📶", 262: "⏰",
  263: "🛏", 264: "🍼", 266: "🛎", 270: "💿", 271: "📀", 275: "🛏", 276: "🧴", 279: "🖥",
  280: "🧖", 281: "🩴", 282: "🪞", 288: "📺", 295: "📐", 298: "🛏", 300: "🧹", 303: "🔇",
  307: "🧖", 308: "🏋️", 312: "☀️",
};

// Hotel facilities: specific codes first, then a default per group
const HOTEL_ICONS: Record<string, string> = {
  "70-550": "📶", "70-470": "🏋️", "70-320": "🅿️", "70-562": "✈️", "70-495": "🚐",
  "70-270": "🛎", "70-280": "🧺", "70-310": "🚲", "70-125": "🌳", "70-135": "🌿",
  "70-430": "☀️", "70-30": "🕑", "70-585": "🛎", "70-40": "🔒", "70-70": "🛗",
  "71-130": "🍸", "71-80": "☕", "71-200": "🍽", "71-555": "🍹",
  "72-605": "💼", "72-170": "🎤", "73-395": "🏖", "73-400": "⛱",
  "74-450": "💆", "74-460": "💆", "74-420": "🧖", "74-440": "♨️",
};
const GROUP_ICONS: Record<number, string> = { 70: "🛎", 71: "🍽", 72: "💼", 73: "🏊", 74: "💆", 90: "🏋️" };

const hotelIcon = (f: RawFacility) =>
  HOTEL_ICONS[fkey(f)] ?? GROUP_ICONS[f.facilityGroupCode] ?? "✔️";

/* ----------------------------- features ---------------------------- */

function buildFeatures(fm: Map<string, RawFacility>): HotelView["features"] {
  const out: HotelView["features"] = [];

  const beach = fm.get("40-40");
  if (beach?.distance != null) {
    out.push({ icon: "beach", label: `Beach ${formatDistance(beach.distance)} away` });
  }

  const wifi = fm.get("70-550");
  if (isPresent(wifi)) {
    out.push({ icon: "wifi", label: wifi.indFee ? "Wi-Fi (extra charge)" : "Free Wi-Fi" });
  }

  const indoor = isPresent(fm.get("73-360"));
  const outdoor = isPresent(fm.get("73-363"));
  if (indoor || outdoor) {
    out.push({
      icon: "pool",
      label: indoor && outdoor ? "Indoor & outdoor pools" : indoor ? "Indoor pool" : "Outdoor pool",
    });
  }

  const shuttle = fm.get("70-562");
  const transfer = fm.get("70-495");
  const t = isPresent(shuttle) ? shuttle : isPresent(transfer) ? transfer : undefined;
  if (t) {
    out.push({
      icon: "plane",
      label: `${t === shuttle ? "Airport shuttle" : "Transfer service"}${t.indFee ? " (fee)" : ""}`,
    });
  }

  if (isPresent(fm.get("74-460")) || isPresent(fm.get("74-420"))) {
    out.push({ icon: "spa", label: "Spa & wellness" });
  }

  const restaurant = fm.get("71-200");
  if (isPresent(restaurant)) {
    const n = restaurant.number ?? 1;
    out.push({ icon: "food", label: n > 1 ? `${n} restaurants` : "Restaurant" });
  }

  if (isPresent(fm.get("71-130"))) out.push({ icon: "bar", label: "Bar" });

  if (isPresent(fm.get("70-470")) || isPresent(fm.get("90-295"))) {
    out.push({ icon: "gym", label: "Gym & fitness" });
  }

  const parking = fm.get("70-320");
  if (isPresent(parking)) {
    out.push({ icon: "car", label: parking.indFee ? "Car park (fee)" : "Car park" });
  }

  if (isPresent(fm.get("70-30"))) out.push({ icon: "clock", label: "24-hour reception" });

  return out.slice(0, 8);
}

/* ------------------------------ rates ------------------------------ */

type RateCtx = {
  currency: string;
  nights: number;
  bookHref: (rateKey: string) => string;
};

function cancelText(r: RawRate): string {
  const policies = [...(r.cancellationPolicies ?? [])].sort(
    (a, b) => new Date(a.from).getTime() - new Date(b.from).getTime()
  );
  if (!policies.length) return "Check cancellation policy";
  const first = new Date(policies[0].from);
  if (Number.isNaN(first.getTime())) return "Check cancellation policy";
  return first.getTime() > Date.now()
    ? `Free cancellation until ${shortDate(policies[0].from)}`
    : "Non-refundable";
}

function taxText(r: RawRate, fallbackCurrency: string): string | undefined {
  const due = (r.taxes?.taxes ?? []).filter((t) => t.included === false && (t.clientAmount ?? t.amount));
  if (!due.length) return undefined;
  const cur = due[0].clientCurrency ?? due[0].currency ?? fallbackCurrency;
  const sum = due
    .filter((t) => (t.clientCurrency ?? t.currency ?? fallbackCurrency) === cur)
    .reduce((acc, t) => acc + Number(t.clientAmount ?? t.amount ?? 0), 0);
  return sum > 0 ? `+ ${money(sum, cur)} taxes payable at the hotel` : undefined;
}

function buildRates(rates: RawRate[], ctx: RateCtx): RateView[] {
  return rates
    .map((r): RateView | null => {
      const amount = Number(r.sellingRate ?? r.net);
      if (!Number.isFinite(amount)) return null;
      const perNight = amount / ctx.nights;
      return {
        key: r.rateKey,
        board: titleCase(r.boardName ?? r.boardCode ?? "Room only"),
        cancel: cancelText(r),
        payment: r.paymentType === "AT_HOTEL" ? "Pay at the hotel" : r.paymentType === "AT_WEB" ? "Pay now" : undefined,
        taxNote: taxText(r, ctx.currency),
        allotment: r.allotment ?? 0,
        total: money(amount, ctx.currency),
        sub: `${money(perNight, ctx.currency)} per night · ${ctx.nights} night${ctx.nights > 1 ? "s" : ""}`,
        amount,
        href: ctx.bookHref(r.rateKey),
      };
    })
    .filter((x): x is RateView => x !== null)
    .sort((a, b) => a.amount - b.amount);
}

/* ------------------------------ rooms ------------------------------ */

function roomFacilityList(r: RawRoom): IconLabel[] {
  const size: IconLabel[] = [];
  const bedrooms: IconLabel[] = [];
  const rest: IconLabel[] = [];

  for (const f of r.roomFacilities ?? []) {
    if (f.facilityGroupCode !== 60) continue;

    // 295 = room size (sqm), 298 = number of bedrooms: driven by `number`
    if (f.facilityCode === 295) {
      if (f.number) size.push({ icon: ROOM_ICONS[295], label: `${f.number} m²` });
      continue;
    }
    if (f.facilityCode === 298) {
      if (f.number) bedrooms.push({ icon: ROOM_ICONS[298], label: f.number > 1 ? `${f.number} bedrooms` : "1 bedroom" });
      continue;
    }

    if (!isPresent(f)) continue;
    const d = f.description?.content?.trim();
    if (!d) continue;
    rest.push({
      icon: ROOM_ICONS[f.facilityCode] ?? "✔️",
      label: f.facilityCode === 261 && f.indFee ? "Wi-Fi (fee)" : d,
    });
  }

  const seen = new Set<string>();
  return [...size, ...bedrooms, ...rest].filter((x) => !seen.has(x.label) && !!seen.add(x.label));
}

function buildRooms(h: RawHotel, avail: RawAvailHotel | null, ctx: RateCtx | null): RoomView[] {
  const all = h.rooms ?? [];

  // images grouped by roomCode, lowest visualOrder first
  const byRoom = new Map<string, RawImage[]>();
  for (const img of [...(h.images ?? [])].sort((a, b) => a.visualOrder - b.visualOrder)) {
    if (!img.roomCode) continue;
    const list = byRoom.get(img.roomCode) ?? [];
    list.push(img);
    byRoom.set(img.roomCode, list);
  }

  // rates grouped by room code (availability room.code === content roomCode)
  const ratesByRoom = new Map<string, RateView[]>();
  if (avail && ctx) {
    for (const r of avail.rooms ?? []) {
      const list = buildRates(r.rates ?? [], ctx);
      if (list.length) ratesByRoom.set(r.code, [...(ratesByRoom.get(r.code) ?? []), ...list].sort((a, b) => a.amount - b.amount));
    }
  }

  // Parent rooms carry the detailed data; also keep rooms with photos or with rates.
  const source = all.filter((r) => r.isParentRoom || byRoom.has(r.roomCode) || ratesByRoom.has(r.roomCode));
  const rooms = source.length ? source : all.slice(0, 12);

  const marketing = new Map(
    (h.wildcards ?? []).map((w) => [w.roomType, w.hotelRoomDescription?.content])
  );

  return rooms
    .map((r) => ({
      room: r,
      view: {
        code: r.roomCode,
        title: marketing.get(r.roomCode) ?? titleCase(r.description),
        type: titleCase(r.type?.description?.content),
        characteristic: titleCase(r.characteristic?.description?.content),
        minPax: r.minPax,
        maxPax: r.maxPax,
        maxAdults: r.maxAdults,
        maxChildren: r.maxChildren,
        beds: (r.roomStays?.[0]?.roomStayFacilities ?? [])
          .filter((b) => b.description?.content)
          .map((b) => `${b.number ?? 1} × ${b.description!.content!.trim()}`),
        facilities: roomFacilityList(r),
        images: (byRoom.get(r.roomCode) ?? [])
          .slice(0, MAX_IMAGES_PER_ROOM)
          .map((img) => ({ full: imageUrl(img.path, "bigger"), thumb: imageUrl(img.path, "medium") })),
        rates: ratesByRoom.get(r.roomCode) ?? [],
      } satisfies RoomView,
    }))
    .sort((a, b) => {
      // bookable rooms first (cheapest first), then parent rooms
      const ra = a.view.rates[0]?.amount ?? Infinity;
      const rb = b.view.rates[0]?.amount ?? Infinity;
      if (ra !== rb) return ra - rb;
      return Number(!!b.room.isParentRoom) - Number(!!a.room.isParentRoom);
    })
    .map((x) => x.view);
}

/* ------------------------------------------------------------------ */
/* Mapper                                                              */
/* ------------------------------------------------------------------ */

export type ToHotelViewOptions = {
  availability?: RawAvailHotel | null;
  checkIn?: string;
  checkOut?: string;
  nights?: number;
  /** builds the link behind the Book button */
  bookHref?: (rateKey: string) => string;
};

export function toHotelView(h: RawHotel, opts: ToHotelViewOptions = {}): HotelView {
  const facilities = h.facilities ?? [];
  const fm = new Map(facilities.map((f) => [fkey(f), f]));

  const name = h.name?.content?.trim() ?? "Hotel";

  const seen = new Set<string>();
  const location = [
    titleCase(h.city?.content),
    h.destination?.name?.content,
    h.country?.description?.content,
  ]
    .filter((p): p is string => !!p && !seen.has(p.toLowerCase()) && !!seen.add(p.toLowerCase()))
    .join(", ");

  const images = [...(h.images ?? [])].sort((a, b) => a.visualOrder - b.visualOrder);
  const photos = images.slice(0, 5).map((img, i) => ({
    src: imageUrl(img.path, i === 0 ? "bigger" : "medium"),
    alt: `${name} – ${img.type?.description?.content ?? "photo"}`,
  }));

  const street = h.address?.street?.trim();
  const number = h.address?.number?.trim();
  const streetLine = street ? (number ? `${street}, ${number}` : street) : h.address?.content ?? "";
  const address = [streetLine, [h.postalCode, titleCase(h.city?.content)].filter(Boolean).join(" ")]
    .filter(Boolean)
    .join(", ");

  const FACILITY_GROUPS = new Set([70, 71, 72, 73, 74, 90]);
  const seenFac = new Set<string>();
  const facilityList: IconLabel[] = facilities
    .filter((f) => FACILITY_GROUPS.has(f.facilityGroupCode) && isPresent(f))
    .map((f) => ({ label: f.description?.content?.trim() ?? "", icon: hotelIcon(f) }))
    .filter((x) => x.label && !seenFac.has(x.label) && !!seenFac.add(x.label));

  const distances = facilities
    .filter((f) => f.facilityGroupCode === 40 && f.distance != null && f.description?.content)
    .map((f) => ({ label: f.description!.content!, value: formatDistance(f.distance!) }));

  // pricing
  const nights = Math.max(1, opts.nights ?? 1);
  const avail = opts.availability ?? null;
  const currency = avail?.currency ?? "EUR";
  const ctx: RateCtx | null =
    avail && opts.bookHref ? { currency, nights, bookHref: opts.bookHref } : null;

  const rooms = buildRooms(h, avail, ctx);
  const cheapest = rooms.flatMap((r) => r.rates).sort((a, b) => a.amount - b.amount)[0];

  const stayLabel =
    opts.checkIn && opts.checkOut
      ? `${shortDate(opts.checkIn)} – ${shortDate(opts.checkOut)} · ${nights} night${nights > 1 ? "s" : ""}`
      : undefined;

  const c = h.coordinates;

  return {
    id: h.code,
    name,
    stars: parseStars(h),
    location,
    heading: `About ${name}`,
    description: h.description?.content?.trim() ?? "",
    features: buildFeatures(fm),
    photos,
    photoCount: images.length,
    rooms,
    facilities: facilityList,
    distances,
    address,
    checkIn: fm.get("70-260")?.timeFrom?.slice(0, 5),
    checkOut: fm.get("70-390")?.timeTo?.slice(0, 5),
    mapUrl: c ? `https://www.google.com/maps?q=${c.latitude},${c.longitude}` : undefined,
    priced: !!cheapest,
    stayLabel,
    fromPrice: cheapest ? money(cheapest.amount / nights, currency) : undefined,
    review: null,
  };
}