import { notFound } from "next/navigation";
import HotelOverview from "./HotelOverview";
import { countNights, parseSearchParams } from "@/lib/hotels";
import {
  fetchHotelAvailability,
  fetchHotelDetails,
  toHotelView,
} from "@/lib/view-hotels";

export default async function HotelPage({
  params,
  searchParams,
}: {
  params: Promise<{ id: string }>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  const { id } = await params;
  const search = parseSearchParams(await searchParams);

  // details and availability in parallel
  const [raw, availability] = await Promise.all([
    fetchHotelDetails(id),
    fetchHotelAvailability(id, search),
  ]);
  if (!raw) notFound();

  // ⚠️ adjust to your real booking / checkout route
  const bookHref = (rateKey: string) =>
    `/hotels/${id}/book?${new URLSearchParams({
      rateKey,
      checkIn: search.checkIn,
      checkOut: search.checkOut,
      adults: String(search.adults),
      children: String(search.children),
      rooms: String(search.rooms),
    })}`;

  const hotel = toHotelView(raw, {
    availability,
    checkIn: search.checkIn,
    checkOut: search.checkOut,
    nights: search.checkIn && search.checkOut ? countNights(search.checkIn, search.checkOut) : 1,
    bookHref,
  });

  return <HotelOverview hotel={hotel} />;
}